using CwcConfigurator.Domain;

namespace CwcConfigurator.Services.Simulation;

/// <summary>
/// Byte layout of the PLC simulator DB (DB30 "SIMULATOR", standard access) as generated by TIA:
/// DI, AI, COUNTER, RTD, DO, AO, each a matrix Array[0..MODUL_NUM] of Struct { CH : Array[0..CH_NUM] }.
/// In a standard DB every structure starts on an even byte, so each module of a Bool matrix takes an even
/// number of bytes. Note: the DO matrix uses DI_CH_NUM for its channels (DT_MATRIX_DO in the PLC).
/// </summary>
public sealed record SimulatorLayout(
    int DiModules,
    int DiChannels,
    int AiModules,
    int AiChannels,
    int CounterModules,
    int RtdModules,
    int RtdChannels,
    int DoModules,
    int DoChannels,
    int AoModules,
    int AoChannels)
{
    public const int DefaultDbNumber = 30;

    /// <summary>Sizes from the template PLC constants (DI 16×16, AI 6×8, COUNTER 4, RTD 6×8, DO 16×16, AO 3×4).</summary>
    public static SimulatorLayout Default { get; } = new(16, 16, 6, 8, 4, 6, 8, 16, 16, 3, 4);

    public int DiStart => 0;
    public int AiStart => Even(DiStart + DiModules * BoolModuleBytes(DiChannels));
    public int CounterStart => Even(AiStart + AiModules * AiChannels * 2);
    public int RtdStart => Even(CounterStart + CounterModules * 4);
    public int DoStart => Even(RtdStart + RtdModules * RtdChannels * 2);
    public int AoStart => Even(DoStart + DoModules * BoolModuleBytes(DoChannels));
    public int TotalBytes => Even(AoStart + AoModules * AoChannels * 2);

    /// <summary>Names of the PLC constants (TIA tag table) in the order of <see cref="ToConstants"/>.</summary>
    public static IReadOnlyList<string> ConstantNames { get; } =
    [
        "DI_MODUL_NUM", "DI_CH_NUM", "AI_MODUL_NUM", "AI_CH_NUM", "COUNTER_MODUL_NUM",
        "RTD_MODUL_NUM", "RTD_CH_NUM", "DO_MODUL_NUM", "AO_MODUL_NUM", "AO_CH_NUM"
    ];

    /// <summary>
    /// Proposed sizes for one PLC database: the template constants, enlarged where the hardware tables of the
    /// database have more modules or channels. The PLC constants decide; the user can correct them in the window.
    /// </summary>
    public static SimulatorLayout FromProject(CwcProject project)
    {
        var fallback = Default;
        var diChannels = Math.Max(fallback.DiChannels, Channels(project.DigitalInputs.Select(row => row.Port)));
        return new SimulatorLayout(
            Math.Max(fallback.DiModules, Modules(project.DigitalInputs.Select(row => row.ModuleNumber))),
            diChannels,
            Math.Max(fallback.AiModules, Modules(project.AnalogInputs.Select(row => row.ModuleNumber))),
            Math.Max(fallback.AiChannels, Channels(project.AnalogInputs.Select(row => row.Port))),
            Math.Max(fallback.CounterModules, Modules(project.Counters.Select(row => row.ModuleNumber))),
            Math.Max(fallback.RtdModules, Modules(project.RtdInputs.Select(row => row.ModuleNumber))),
            Math.Max(fallback.RtdChannels, Channels(project.RtdInputs.Select(row => row.Port))),
            Math.Max(fallback.DoModules, Modules(project.DigitalOutputs.Select(row => row.ModuleNumber))),
            diChannels,
            Math.Max(fallback.AoModules, Modules(project.AnalogOutputs.Select(row => row.ModuleNumber))),
            Math.Max(fallback.AoChannels, Channels(project.AnalogOutputs.Select(row => row.Port))));
    }

    /// <summary>Layout from the PLC constants (highest index, e.g. DI_MODUL_NUM = 15 means 16 modules).</summary>
    public static SimulatorLayout FromConstants(IReadOnlyList<int> constants)
    {
        if (constants.Count != ConstantNames.Count || constants.Any(value => value < 0))
        {
            throw new ArgumentException($"Expected {ConstantNames.Count} constants of 0 or more.", nameof(constants));
        }

        return new SimulatorLayout(
            constants[0] + 1, constants[1] + 1, constants[2] + 1, constants[3] + 1, constants[4] + 1,
            constants[5] + 1, constants[6] + 1, constants[7] + 1, constants[1] + 1, constants[8] + 1, constants[9] + 1);
    }

    public int[] ToConstants()
    {
        return [DiModules - 1, DiChannels - 1, AiModules - 1, AiChannels - 1, CounterModules - 1,
                RtdModules - 1, RtdChannels - 1, DoModules - 1, AoModules - 1, AoChannels - 1];
    }

    public (int Byte, int Bit) DiBit(int module, int channel) => BoolAddress(DiStart, DiChannels, module, channel);

    public (int Byte, int Bit) DoBit(int module, int channel) => BoolAddress(DoStart, DoChannels, module, channel);

    public int AiWord(int module, int channel) => AiStart + ((module * AiChannels) + channel) * 2;

    public int RtdWord(int module, int channel) => RtdStart + ((module * RtdChannels) + channel) * 2;

    public int AoWord(int module, int channel) => AoStart + ((module * AoChannels) + channel) * 2;

    public string Describe()
    {
        return $"DI {DiModules}×{DiChannels}, AI {AiModules}×{AiChannels}, COUNTER {CounterModules}, RTD {RtdModules}×{RtdChannels}, " +
               $"DO {DoModules}×{DoChannels}, AO {AoModules}×{AoChannels} = {TotalBytes} bytes";
    }

    private static (int Byte, int Bit) BoolAddress(int start, int channels, int module, int channel)
    {
        return (start + module * BoolModuleBytes(channels) + channel / 8, channel % 8);
    }

    private static int BoolModuleBytes(int channels) => Even((channels + 7) / 8);

    private static int Even(int value) => value + (value & 1);

    private static int Modules(IEnumerable<int> modules) => modules.DefaultIfEmpty(-1).Max() + 1;

    private static int Channels(IEnumerable<int> ports) => ports.DefaultIfEmpty(-1).Max() + 1;
}
